var LEFT = [gEmbBox, gLeft];
var CORE = [gBox, gStack, gAttn, gBar1, gFFN, gBar2, p1.g, p2.g, gSkip1, gSkip2, gFlow, gK];

function renderStack() {
  gStack.clear();
  for (var n = state.K - 1; n >= 1; n--) {
    gStack.rect(572, 417).move(378 + n * 4.5, 78 + n * 5.5).radius(10)
      .fill('#e4e8e8').opacity(0.55)
      .stroke({ color: '#9aa1a5', width: 1.1, dasharray: '7,6' });
  }
  kLabel.plain(state.K === 1 ? '(×K)' : '(×' + state.K + ')');
}

function applyTrace() {
  var s = state.trace, k;
  setOp(LEFT, 1); setOp(CORE, 1); gRight.opacity(1); gVocab.opacity(1);
  for (k = 0; k < 7; k++) {
    rightRows[k].opacity(1); hlSoft[k](false); hlProb[k](false);
    outLabels[k].fill(INK); inLabels[k].fill(INK);
  }
  hlEmb(false); hlAttn(false); p1.hl(false); p2.hl(false); hlB1(false); hlB2(false); hlFFN(false);
  skip1.stroke({ color: INK, width: 2 }); skip2.stroke({ color: INK, width: 2 });
  fanLines.forEach(function (f) { f.node.stroke({ color: FAN, width: 1.1, opacity: 0.95 }); });

  if (s === 'idle') return;
  if (s === 'prefix') {
    hlEmb(true);
    inLabels.forEach(function (l) { l.fill(ACC); });
    setOp(CORE, 0.2); gRight.opacity(0.2); gVocab.opacity(0.2);
  } else if (s === 'attend') {
    hlEmb(true); hlAttn(true);
    inLabels.forEach(function (l) { l.fill(ACC); });
    fanLines.forEach(function (f) {
      if (f.t === 6) { f.node.stroke({ color: ACC, width: 2.6, opacity: 1 }).front(); }
      else { f.node.stroke({ opacity: 0.1 }); }
    });
    gRight.opacity(0.22); gVocab.opacity(0.22);
  } else if (s === 'residual') {
    p1.hl(true); p2.hl(true); hlB1(true); hlB2(true); hlFFN(true);
    skip1.stroke({ color: ACC, width: 3 }); skip2.stroke({ color: ACC, width: 3 });
    setOp(LEFT, 0.45); gRight.opacity(0.22); gVocab.opacity(0.22);
  } else if (s === 'softmax') {
    setOp(LEFT, 0.35); setOp(CORE, 0.45);
    for (k = 0; k < 6; k++) rightRows[k].opacity(0.25);
    hlSoft[6](true); hlProb[6](true); outLabels[6].fill(ACC);
  } else if (s === 'done') {
    for (k = 0; k < 7; k++) { hlSoft[k](true); hlProb[k](true); outLabels[k].fill(ACC); }
    fanLines.forEach(function (f) { if (f.s !== f.t) f.node.stroke({ color: ACC, width: 1.4, opacity: 0.85 }); });
  }
}

/* ---------- interaction handlers ---------- */
function update_numLayers(v) { state.K = Math.round(v); renderStack(); applyTrace(); }
function toggle_maskMode(on) { state.unmasked = !!on; drawFan(state.unmasked); applyTrace(); }
var traceStates = ['idle', 'prefix', 'attend', 'residual', 'softmax', 'done'];
function set_trace(v) {
  state.trace = v;
  var sel = document.getElementById('tracePredictionInput');
  if (sel && sel.value !== v) sel.value = v;
  applyTrace();
}
function traceNext() {
  var idx = traceStates.indexOf(state.trace);
  set_trace(traceStates[(idx + 1) % traceStates.length]);
}
function traceReset() { set_trace('idle'); }

/* ---------- demo step player ---------- */
var steps = [
  { title: 'The pipeline at a glance', narration: 'Seven tokens enter as embedding vectors on the left and leave as seven probability distributions over the whole vocabulary on the right. Notice the output labels are the input sequence shifted by one: each position predicts the next token.', state: { numLayers: 1, maskMode: 'Causal mask', tracePrediction: 'idle' } },
  { title: 'Inside one decoder block', narration: 'Click the orange attention panel, the ⊕ nodes, and the teal bars: masked attention mixes information across positions, then each residual addition carries the original vector forward so the block only has to learn a correction.', state: { numLayers: 1, maskMode: 'Causal mask', tracePrediction: 'idle' } },
  { title: 'Why the triangle?', narration: 'Switch to unmasked attention and the connection fan fills in above the diagonal — now the vector at "let" can see "yourself", and predicting it is cheating. Switching back restores the lower-triangular causal mask.', state: { numLayers: 1, maskMode: 'Unmasked (all-to-all)', tracePrediction: 'idle' } },
  { title: 'Unrolling ×K', narration: 'Increase K and the single block expands into a stack of identical blocks. The shape of the computation never changes; only the number of times the sequence is re-mixed and refined.', state: { numLayers: 4, maskMode: 'Causal mask', tracePrediction: 'idle' } },
  { title: 'Tracing one prediction', narration: 'Step the trace: the prefix &ldquo;&lt;start&gt; It takes great courage to let&rdquo; lights up, attention lines flow only from those positions into the last row, residuals add, and the final Linear + softmax produces the distribution whose target is "yourself".', state: { numLayers: 4, maskMode: 'Causal mask', tracePrediction: 'attend' } },
  { title: 'All predictions at once', narration: 'Finish the trace and every row highlights: the same forward pass simultaneously predicts It, takes, great, courage, to, let and yourself — this parallel, shifted training is what makes decoder transformers efficient.', state: { numLayers: 4, maskMode: 'Causal mask', tracePrediction: 'done' } }
];
var curStep = 0;
function applyStepState(st) {
  var sl = document.getElementById('numLayersInput');
  sl.value = st.numLayers;
  document.getElementById('numLayersVal').value = st.numLayers;
  update_numLayers(st.numLayers);
  var cb = document.getElementById('maskModeInput');
  cb.checked = (st.maskMode === 'Unmasked (all-to-all)');
  toggle_maskMode(cb.checked);
  set_trace(st.tracePrediction);
}
function showStep(idx) {
  curStep = (idx + steps.length) % steps.length;
  var s = steps[curStep];
  document.getElementById('demoNarration').innerHTML = '<b>' + s.title + '</b><br>' + s.narration;
  document.getElementById('stepLabel').textContent = 'Step ' + (curStep + 1) + ' / ' + steps.length;
  applyStepState(s.state);
}
function nextStep() { showStep(curStep + 1); }
function prevStep() { showStep(curStep - 1); }
function resetView() { hidePopup(); hideTooltip(); showStep(0); }

/* ---------- init: default view = K 1, causal mask, no trace ---------- */
drawFan(false);
renderStack();
showStep(0);
window.__markRendered();
// @FIGURE_CODE_END

Fix all identified failure modes and improve every score. Maintain or improve what already works well.
Return ONLY the updated marker-wrapped payload.

