<!-- @FIGURE_UI_END -->
// @FIGURE_CODE_BEGIN
var draw = SVG().addTo(document.getElementById('container')).size('100%', '100%');
/* Tightened viewBox (less horizontal whitespace than the first pass) so every
   label renders larger when the figure is docked next to the control panel. */
var FW = 1540, FH = 660;
draw.viewbox(0, 0, FW, FH);

var SERIF = 'Georgia,"Times New Roman",Times,serif';
var INK = '#111', ACC = '#ff7a18';
var ORANGE = '#d1785a', ATTN_EDGE = '#4a2b1e', FAN = '#2b140b';
var TEAL = '#7fcdbb', TEAL_EDGE = '#2e6d61';
var BOXBG = '#c9cdcd', BLUE = '#93b0c6', BLUEST = '#3f5a6b';

/* type scale — chosen so the smallest label lands above ~11 px on screen
   when the 1540-unit viewBox is fitted into a ~560 px inline stage */
var FS_HEAD = 34, FS_TOK = 32, FS_VOC = 30, FS_K = 32, FS_KSUB = 24;

var rowY = [], i, c;
for (i = 0; i < 7; i++) rowY.push(125 + i * 62);
var MIDY = rowY[3];
var inTok = ['<start>', 'It', 'takes', 'great', 'courage', 'to', 'let'];
var outTok = ['It', 'takes', 'great', 'courage', 'to', 'let', 'yourself'];

/* ---------- helpers ---------- */
function label(parent, s, x, y, size, anchor, fill, halo) {
  var t = parent.plain(s).font({ family: SERIF, size: size, anchor: anchor || 'middle' }).fill(fill || INK);
  t.attr({ x: x, y: y, 'dominant-baseline': 'central' });
  if (halo) t.attr({ 'paint-order': 'stroke', stroke: '#fff', 'stroke-width': 4.5, 'stroke-linejoin': 'round' });
  return t;
}
function pts(arr) { return arr.map(function (p) { return p[0] + ',' + p[1]; }).join(' '); }
function harrow(parent, x1, x2, y, color, width) {
  var g = parent.group(), col = color || INK, w = width || 1.8;
  g.line(x1, y, x2 - 7, y).stroke({ color: col, width: w, linecap: 'round' });
  g.polygon(pts([[x2, y], [x2 - 9, y - 4.8], [x2 - 9, y + 4.8]])).fill(col);
  return g;
}
function downHead(parent, x, y, color) {
  return parent.polygon(pts([[x, y], [x - 4.8, y - 9], [x + 4.8, y - 9]])).fill(color || INK);
}
function hlShape(shape, baseColor, baseW) {
  return function (on) { shape.stroke({ color: on ? ACC : baseColor, width: on ? baseW + 1.9 : baseW }); };
}
function attach(node, tip, title, body) {
  node.css('cursor', 'pointer');
  node.on('mousemove', function (e) { showTooltip(tip, e); });
  node.on('mouseleave', function () { hideTooltip(); });
  node.on('click', function () { showPopup(title, body); });
}
function setOp(list, v) { for (var k = 0; k < list.length; k++) list[k].opacity(v); }

/* ---------- 1. stacked layer copies (behind everything) ---------- */
var gStack = draw.group();

/* ---------- 2. transformer grey box ---------- */
var gBox = draw.group();
var boxRect = gBox.rect(520, 470).move(376, 76).radius(12)
  .fill(BOXBG).stroke({ color: '#333', width: 2.4, dasharray: '11,8' });

/* ---------- 3. embedding container ---------- */
var gEmbBox = draw.group();
var embContainer = gEmbBox.rect(172, 432).move(148, 95).radius(3)
  .fill('#ffffff').stroke({ color: '#333', width: 2.4, dasharray: '11,8' });
var hlEmb = hlShape(embContainer, '#333', 2.4);

/* ---------- 4. left column: tokens, embedding rows, bus ---------- */
var gLeft = draw.group();
gLeft.line(332, rowY[0], 332, rowY[6]).stroke({ color: INK, width: 2.2 });
var inLabels = [], leftRows = [];
for (i = 0; i < 7; i++) {
  var lr = gLeft.group();
  harrow(lr, 128, 146, rowY[i]);
  for (c = 0; c < 6; c++) {
    lr.rect(26, 28).move(156 + c * 26, rowY[i] - 14).fill('#fff').stroke({ color: INK, width: 1.6 });
  }
  lr.line(312, rowY[i], 332, rowY[i]).stroke({ color: INK, width: 1.8 });
  inLabels.push(label(lr, inTok[i], 124, rowY[i], FS_TOK, 'end', INK, true));
  attach(lr, 'Embedding vector for "' + inTok[i] + '" (position ' + (i + 1) + ')',
    'Word embedding',
    'Each input token is looked up in an embedding table and becomes a vector of numbers (the row of empty cells). Position ' + (i + 1) + ' holds "' + inTok[i] + '". All seven vectors are fed into the transformer together, in one parallel pass.');
  leftRows.push(lr);
}
harrow(gLeft, 332, 396, MIDY, INK, 3.2);

/* ---------- 5. masked self-attention ---------- */
var gAttn = draw.group();
var attnPanel = gAttn.rect(152, 426).move(400, 98).radius(11)
  .fill(ORANGE).stroke({ color: ATTN_EDGE, width: 1.8 });
var hlAttn = hlShape(attnPanel, ATTN_EDGE, 1.8);
var gFan = gAttn.group();
var fanLines = [];
function drawFan(unmasked) {
  gFan.clear(); fanLines = [];
  var x1 = 405, x2 = 547;   /* fan spans essentially the full panel width */
  for (var s = 0; s < 7; s++) {
    for (var t = 0; t < 7; t++) {
      if (!unmasked && t < s) continue;
      var ln = gFan.line(x1, rowY[s], x2, rowY[t]).stroke({ color: FAN, width: 1.7, opacity: 1 });
      fanLines.push({ node: ln, s: s, t: t });
    }
  }
}
attach(gAttn, 'Masked self-attention: each position reads only itself and earlier positions',
  'Masked self-attention',
  'Every line is one position reading another. With the causal mask the fan is lower-triangular: position j mixes information only from positions 1…j, never from later tokens. That is what lets the same forward pass predict the next token at every position without ever seeing the answer.');

/* ---------- 6. residual / layer-norm / feedforward ---------- */
var gBar1 = draw.group();
var bar1 = gBar1.rect(16, 426).move(620, 98).radius(8).fill(TEAL).stroke({ color: TEAL_EDGE, width: 1.6 });
var hlB1 = hlShape(bar1, TEAL_EDGE, 1.6);
attach(gBar1, 'Layer norm / feature vectors after attention', 'Post-attention normalisation',
  'The teal bar stands for the normalised bundle of feature vectors — one per position — after attention has mixed information across positions. Normalisation keeps activations at a stable scale so deep stacks stay trainable.');

var gFFN = draw.group();
var ffnRect = gFFN.rect(156, 426).move(658, 98).radius(2).fill('none').stroke({ color: INK, width: 2.2 });
var hlFFN = hlShape(ffnRect, INK, 2.2);
gFFN.line(666, rowY[0], 666, rowY[6]).stroke({ color: INK, width: 1.8 });
for (i = 0; i < 7; i++) {
  harrow(gFFN, 666, 716, rowY[i]);
  gFFN.rect(54, 26).move(718, rowY[i] - 13).radius(13).fill(BLUE).stroke({ color: BLUEST, width: 1.5 });
  gFFN.line(772, rowY[i], 800, rowY[i]).stroke({ color: INK, width: 1.8 });
}
gFFN.line(800, rowY[0], 800, rowY[6]).stroke({ color: INK, width: 2.2 });
attach(gFFN, 'Position-wise feedforward network (same weights at every position)',
  'Position-wise feedforward',
  'Each of the seven pills is the SAME small neural network applied independently to one position\'s vector. No information crosses positions here — all cross-position mixing already happened in masked attention.');

var gBar2 = draw.group();
var bar2 = gBar2.rect(16, 426).move(866, 98).radius(8).fill(TEAL).stroke({ color: TEAL_EDGE, width: 1.6 });
var hlB2 = hlShape(bar2, TEAL_EDGE, 1.6);
attach(gBar2, 'Layer norm output of the decoder block', 'Block output',
  'The output of one decoder block: seven refined vectors, one per position, ready to enter the next identical block. Increase K in the panel to stack more of these blocks.');

/* plus nodes */
function plusNode(x, y) {
  var g = draw.group();
  var circ = g.circle(28).center(x, y).fill('#fff').stroke({ color: INK, width: 2.2 });
  g.line(x - 9, y, x + 9, y).stroke({ color: INK, width: 2.2 });
  g.line(x, y - 9, x, y + 9).stroke({ color: INK, width: 2.2 });
  return { g: g, circle: circ, hl: hlShape(circ, INK, 2.2) };
}
/* skip connections drawn before plus nodes so circles sit on top */
var gSkip1 = draw.group();
var skip1 = gSkip1.polyline(pts([[396, MIDY], [396, 92], [588, 92], [588, MIDY - 23]]))
  .fill('none').stroke({ color: INK, width: 2.2 });
downHead(gSkip1, 588, MIDY - 14);
var gSkip2 = draw.group();
var skip2 = gSkip2.polyline(pts([[650, MIDY], [650, 92], [840, 92], [840, MIDY - 23]]))
  .fill('none').stroke({ color: INK, width: 2.2 });
downHead(gSkip2, 840, MIDY - 14);

var p1 = plusNode(588, MIDY), p2 = plusNode(840, MIDY);
attach(p1.g, 'Residual addition after attention', 'Residual connection',
  'The line routed over the attention panel carries the original vectors straight to this ⊕. Adding them back means the block only has to learn a correction to what it already had, which makes very deep stacks trainable.');
attach(p2.g, 'Residual addition after the feedforward', 'Residual connection',
  'A second skip line adds the pre-feedforward vectors to the feedforward output. Attention + residual, feedforward + residual: that pair is the entire decoder block, repeated K times.');

/* internal connectors */
var gFlow = draw.group();
harrow(gFlow, 552, 572, MIDY);
harrow(gFlow, 602, 618, MIDY);
harrow(gFlow, 636, 660, MIDY);
harrow(gFlow, 800, 826, MIDY);
harrow(gFlow, 854, 866, MIDY);
harrow(gFlow, 882, 928, MIDY);
harrow(gFlow, 984, 1022, MIDY);

/* ---------- 7. (×K) badge and ellipsis ---------- */
var gK = draw.group();
[940, 956, 972].forEach(function (x) { gK.circle(7.2).center(x, MIDY).fill(INK); });
var kLabel = label(gK, '(×K)', 956, 258, FS_K, 'middle', INK, true);
var kSub = label(gK, '', 956, 362, FS_KSUB, 'middle', '#444', true);
attach(gK, 'The decoder block is repeated K times', 'Repeated ×K',
  'One decoder block is applied over and over — K identical blocks with their own weights. The shape of the computation never changes; only how many times the sequence is re-mixed and refined. Drag the "Decoder layers K" slider to unroll the stack.');
attach(gStack, 'Stack of K identical decoder blocks', 'Stacked decoder blocks',
  'Each faint card behind the main block is another identical decoder layer: masked attention → ⊕ → feedforward → ⊕. Depth is a design choice, not part of the causal-masking mechanism.');

/* ---------- 8. right column: linear+softmax, probabilities, targets ---------- */
var gRight = draw.group();
var gOutBus = gRight.group();
gOutBus.line(1024, rowY[0], 1024, rowY[6]).stroke({ color: INK, width: 2.2 });
var rightRows = [], hlSoft = [], hlProb = [], outLabels = [];
for (i = 0; i < 7; i++) {
  var rr = gRight.group();
  harrow(rr, 1024, 1050, rowY[i]);
  var sb = rr.rect(120, 46).move(1054, rowY[i] - 23).radius(23)
    .fill(TEAL).stroke({ color: TEAL_EDGE, width: 1.8 });
  hlSoft.push(hlShape(sb, TEAL_EDGE, 1.8));
  harrow(rr, 1174, 1200, rowY[i]);
  var cells = [];
  for (c = 0; c < 3; c++) {
    cells.push(rr.rect(28, 30).move(1204 + c * 28, rowY[i] - 15).fill(BLUE).stroke({ color: BLUEST, width: 1.4 }));
  }
  rr.line(1288, rowY[i] - 15, 1334, rowY[i] - 15).stroke({ color: BLUEST, width: 1.4, dasharray: '2,4' });
  rr.line(1288, rowY[i] + 15, 1334, rowY[i] + 15).stroke({ color: BLUEST, width: 1.4, dasharray: '2,4' });
  [1298, 1311, 1324].forEach(function (x) { rr.circle(4.6).center(x, rowY[i]).fill(BLUEST); });
  for (c = 0; c < 2; c++) {
    cells.push(rr.rect(28, 30).move(1334 + c * 28, rowY[i] - 15).fill(BLUE).stroke({ color: BLUEST, width: 1.4 }));
  }
  (function (cs) {
    hlProb.push(function (on) {
      cs.forEach(function (cc) { cc.stroke({ color: on ? ACC : BLUEST, width: on ? 3 : 1.4 }); });
    });
  })(cells);
  var ol = label(rr, outTok[i], 1402, rowY[i], FS_TOK, 'start', INK, true);
  outLabels.push(ol);
  attach(sb, 'Linear + softmax at position ' + (i + 1) + ' → distribution whose target is "' + outTok[i] + '"',
    'Linear + softmax',
    'A single linear layer projects this position\'s vector onto the whole vocabulary, and softmax turns the scores into probabilities. Position ' + (i + 1) + ' has only seen "' + inTok.slice(0, i + 1).join(' ') + '", so its training target is the next token, "' + outTok[i] + '".');
  attach(ol, 'Target token for position ' + (i + 1), 'Shifted targets',
    'The target labels are the input sequence shifted left by one. That shift, together with the causal mask, is what makes next-token prediction possible in a single parallel pass.');
  rightRows.push(rr);
  (function (idx, cellList) {
    cellList.forEach(function (cc) {
      attach(cc, 'One vocabulary entry\'s probability (row target: "' + outTok[idx] + '")',
        'Probability of target token',
        'Each row is a full probability distribution over every word in the vocabulary — the cells shown stand for a / aardvark / abacus … zeta / zero. Training pushes probability mass onto the one correct next token, here "' + outTok[idx] + '".');
    });
  })(i, cells);
}

/* ---------- vocabulary band under the bottom probability row ---------- */
var gVocab = draw.group();
var VOC_TOP = rowY[6] + 34;                     /* common top edge for all five labels */
var vocab = [[1218, 'a'], [1246, 'aardvark'], [1274, 'abacus'], [1348, 'zeta'], [1376, 'zero']];
vocab.forEach(function (v) {
  var t = label(gVocab, v[1], v[0], VOC_TOP, FS_VOC, 'end', INK, false);
  t.rotate(-90, v[0], VOC_TOP);
});
[1300, 1311, 1322].forEach(function (x) { gVocab.circle(5).center(x, VOC_TOP + 20).fill(INK); });
attach(gVocab, 'Vocabulary axis: a, aardvark, abacus … zeta, zero', 'The vocabulary axis',
  'The cells of every probability row run along the same vocabulary axis. Only a few entries are drawn; a real model has tens of thousands, and softmax spreads one unit of probability across all of them.');

/* ---------- 9. column headings ---------- */
var gHead = draw.group();
label(gHead, 'Word', 234, 20, FS_HEAD);
label(gHead, 'embeddings', 234, 58, FS_HEAD);
label(gHead, 'Transformer with', 636, 20, FS_HEAD);
label(gHead, 'masked attention', 636, 58, FS_HEAD);
label(gHead, 'Linear +', 1104, 20, FS_HEAD);
label(gHead, 'softmax', 1104, 58, FS_HEAD);
label(gHead, 'Probability of', 1300, 20, FS_HEAD);
label(gHead, 'target token', 1300, 58, FS_HEAD);

/* ---------- state + rendering ---------- */
var state = { K: 1, unmasked: false, trace: 'idle' };
var LEFT = [gEmbBox, gLeft];
var CORE = [gBox, gStack, gAttn, gBar1, gFFN, gBar2, p1.g, p2.g, gSkip1, gSkip2, gFlow, gK];

function renderStack() {
  gStack.clear();
  for (var n = state.K - 1; n >= 1; n--) {
    gStack.rect(520, 470).move(376 + n * 5, 76 + n * 6).radius(12)
      .fill('#e4e8e8').opacity(0.55)
      .stroke({ color: '#9aa1a5', width: 1.2, dasharray: '8,7' });
  }
  kLabel.plain('(×K)');                                   /* badge text stays literal */
  kSub.plain(state.K === 1 ? '' : 'K = ' + state.K);
}

function applyTrace() {
  var s = state.trace, k;
  setOp(LEFT, 1); setOp(CORE, 1); gRight.opacity(1); gVocab.opacity(1);
  for (k = 0; k < 7; k++) {
    rightRows[k].opacity(1); hlSoft[k](false); hlProb[k](false);
    outLabels[k].fill(INK); inLabels[k].fill(INK);
  }
  hlEmb(false); hlAttn(false); p1.hl(false); p2.hl(false); hlB1(false); hlB2(false); hlFFN(false);
  skip1.stroke({ color: INK, width: 2.2 }); skip2.stroke({ color: INK, width: 2.2 });
  fanLines.forEach(function (f) { f.node.stroke({ color: FAN, width: 1.7, opacity: 1 }); });

  if (s === 'idle') return;
  if (s === 'prefix') {
    hlEmb(true);
    inLabels.forEach(function (l) { l.fill(ACC); });
    setOp(CORE, 0.2); gRight.opacity(0.2); gVocab.opacity(0.2);
  } else if (s === 'attend') {
    hlEmb(true); hlAttn(true);
    inLabels.forEach(function (l) { l.fill(ACC); });
    fanLines.forEach(function (f) {
      if (f.t === 6) { f.node.stroke({ color: ACC, width: 3, opacity: 1 }).front(); }
      else { f.node.stroke({ opacity: 0.12 }); }
    });
    gRight.opacity(0.22); gVocab.opacity(0.22);
  } else if (s === 'residual') {
    p1.hl(true); p2.hl(true); hlB1(true); hlB2(true); hlFFN(true);
    skip1.stroke({ color: ACC, width: 3.2 }); skip2.stroke({ color: ACC, width: 3.2 });
    setOp(LEFT, 0.45); gRight.opacity(0.22); gVocab.opacity(0.22);
  } else if (s === 'softmax') {
    setOp(LEFT, 0.35); setOp(CORE, 0.45);
    for (k = 0; k < 6; k++) rightRows[k].opacity(0.25);
    hlSoft[6](true); hlProb[6](true); outLabels[6].fill(ACC);
  } else if (s === 'done') {
    for (k = 0; k < 7; k++) { hlSoft[k](true); hlProb[k](true); outLabels[k].fill(ACC); }
    fanLines.forEach(function (f) { if (f.s !== f.t) f.node.stroke({ color: ACC, width: 2, opacity: 0.9 }); });
  }
}

/* ---------- interaction handlers ---------- */
function update_numLayers(v) { state.K = Math.round(v); renderStack(); applyTrace(); }
function toggle_maskMode(on) { state.unmasked = !!on; drawFan(state.unmasked); applyTrace(); }
var traceStates = ['idle', 'prefix', 'attend', 'residual', 'softmax', 'done'];
function set_trace(v) {
  state.trace = v;
  var sel = document.getElementById('tracePredictionInput');
  if (sel && sel.value !== v) sel.value = v;
  applyTrace();
}
function traceNext() {
  var idx = traceStates.indexOf(state.trace);
  set_trace(traceStates[(idx + 1) % traceStates.length]);
}
function traceReset() { set_trace('idle'); }

