  document.getElementById('stepLabel').textContent = 'Step ' + (curStep + 1) + ' / ' + steps.length;
  applyStepState(s.state);
}
function nextStep() { showStep(curStep + 1); }
function prevStep() { showStep(curStep - 1); }
function resetView() { hidePopup(); hideTooltip(); showStep(0); }

